package net.hivel.islandsrpg.currency;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.data.PlayerData; import org.bukkit.entity.Player;
public class CurrencyService { private final IslandsRPGPlugin plugin; public CurrencyService(IslandsRPGPlugin plugin){this.plugin=plugin;} public void addMoney(Player p,long amount){PlayerData d=plugin.data().get(p); d.money=Math.max(0,d.money+amount); plugin.data().save(d);} public void setMoney(Player p,long amount){PlayerData d=plugin.data().get(p); d.money=Math.max(0,amount); plugin.data().save(d);} public void addFragments(Player p,long amount){PlayerData d=plugin.data().get(p); d.fragments=Math.max(0,d.fragments+amount); plugin.data().save(d);} public void setFragments(Player p,long amount){PlayerData d=plugin.data().get(p); d.fragments=Math.max(0,amount); plugin.data().save(d);} }
